# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_aer_a import B
W=[
E('airline','英 /ˈeəlaɪn/；美 /ˈerlaɪn/','航空公司','想象在天空中经营固定线路：不只是一架飞机，而是一整套载客或运货的服务。','air + line；早期可指两点间不随地形绕弯的直线，后来用于航空运输公司。',B+[['air + line → airline','直达路线 → 航空运输企业']],'a budget airline 是廉价航空公司；an airline operates flights 是航空公司运营航班。line 在这里借用了运输线路、运营服务的概念，现代最常见的 airline 就是公司。','a budget airline；an international airline；airline staff；airline tickets。','airline 是公司，airliner 是大型客机，airport 是机场。订票的人经常把这三个对象一起提到，但别混成同一个。',('The airline has added two new routes.','这家航空公司新增了两条航线。'),('We compared fares from several airlines.','我们比较了几家航空公司的票价。'),sources=['https://www.etymonline.com/word/airline','https://en.wiktionary.org/wiki/airline']),
E('airport','英 /ˈeəpɔːt/；美 /ˈerpɔrt/','机场','把海港换成飞机的港口：飞机在这里到达、离开，旅客和货物在这里转接。','air + port 港口；用水上交通的港口意象给航空设施命名。',B+[['air + port → airport','空中的运输港口 → 机场']],'机场不只是跑道，还包括用于航空起降和运营的设施。大型机场会有航站楼、行李处理和交通连接；小机场的设施则可能简单得多。','at the airport；an international airport；airport security；an airport terminal。','airport 是整体机场，terminal 是航站楼。一个机场可以有多个航站楼；airfield 更偏重起降场地。',('We arrived at the airport before sunrise.','我们在日出前到了机场。'),('A train connects the airport to the city center.','有一条铁路连接机场和市中心。'),sources=['https://en.wiktionary.org/wiki/airport','https://www.oxfordlearnersdictionaries.com/definition/english/airport']),
E('aircraft','英 /ˈeəkrɑːft/；美 /ˈerkræft/','航空器；飞行器','只要是用于在空气中飞行的交通器具，就可能进入这个大类。','air + craft；craft 在这里沿用船只、运载工具的用法，不是手工艺品。',B+[['air + craft → aircraft','空中运载工具 → 航空器']],'飞机、直升机、滑翔机等都可称 aircraft。它既是可数名词，又是单复数同形：one aircraft、three aircraft，不加一个 s。','a passenger aircraft；a military aircraft；several aircraft；an aircraft engine。','airplane 是 aircraft 的一种；helicopter 也是 aircraft，但通常不叫 airplane。用更宽的类名时，范围会变化。',('Several aircraft were parked near the hangar.','几架航空器停在机库附近。'),('The aircraft can carry both passengers and cargo.','这架飞机既能载客，也能运货。'),sources=['https://en.wiktionary.org/wiki/aircraft','https://www.oxfordlearnersdictionaries.com/definition/english/aircraft']),
E('aeroplane','英 /ˈeərəpleɪn/；美 /ˈerəpleɪn/','飞机〔常见英式用词〕','抓住 aero- 的空气感：靠机翼在空气中飞行的机器。','直接近源是法语 aéroplane。后半部分有不同词源解释：有的连希腊 planos 游移，有的连法语 planer 滑翔及拉丁 planus 平的。',B[:1]+[['法语 aéroplane','与空气中飞行有关的名称'],['英语 aeroplane','机翼、飞行器相关用法 → 飞机']],'英国英语常说 aeroplane，美国英语常说 airplane，两边都广泛用更短的 plane。词源资料对后半部分分析不一，学习时先记住法语借入和空气中的飞机，不把一种有争议的拆法当定论。','a passenger aeroplane；a model aeroplane；travel by aeroplane。','aeroplane 与 airplane 主要是地区用词习惯不同，不是两种不同结构的飞机。直升机是 helicopter，不能因为也飞就都叫 aeroplane。',('A small aeroplane flew over the fields.','一架小飞机从田野上空飞过。'),('He built a model aeroplane from wood.','他用木头做了一架飞机模型。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/aeroplane','https://www.etymonline.com/word/aeroplane']),
E('airplane','英 /ˈeəpleɪn/；美 /ˈerpleɪn/','飞机〔常见美式用词〕','把不太日常的 aero- 换成人人熟悉的 air，飞机的名称变得更顺口。','由 aeroplane 改形，以英语 air 替换 aero-；今天也容易按 air + plane 理解。',B+[['法语 aéroplane → 英语 aeroplane','飞机名称的前身'],['英语 airplane','把 aero- 改成 air 的形式']],'an airplane ticket 是机票，by airplane 是乘飞机。日常也直接说 plane。这里的 plane 是飞机的短称；不要再把 airplane 机械翻成“空气平面”。','fly an airplane；a passenger airplane；an airplane engine；by airplane。','airplane 和 aeroplane 是同一类飞机的两种叫法；aircraft 的范围更大。',('The airplane circled the airport before landing.','飞机在机场上空盘旋了一圈后降落。'),('She had never traveled by airplane before.','她以前从没坐过飞机。'),sources=['https://www.etymonline.com/word/airplane','https://en.wiktionary.org/wiki/airplane']),
E('airliner','英 /ˈeəlaɪnə/；美 /ˈerlaɪnər/','大型客机；航线客机','不是经营航班的公司，而是那架沿航线运送乘客的飞机。','air + liner；liner 原与按固定航线运营的船有关，再转用于航空器。',B+[['liner 航线客轮 + air → airliner','沿航线运送乘客的飞机']],'a passenger airliner 常指商业载客飞机；a jet airliner 是喷气式客机。它通常比小型私人飞机更让人联想到航空公司的客运服务。','a commercial airliner；a jet airliner；a passenger airliner。','airline 是航空公司，airliner 是客机。an airline owns airliners：公司拥有飞机。',('The airliner can seat more than three hundred passengers.','这架客机可以搭载三百多名乘客。'),('The photograph shows an early jet airliner.','照片中是一架早期喷气式客机。'),sources=['https://en.wiktionary.org/wiki/airliner','https://www.oxfordlearnersdictionaries.com/definition/english/airliner']),
E('aeronautics','英 /ˌeərəˈnɔːtɪks/；美 /ˌeroʊˈnɔtɪks/','航空学；航空技术','把航海的空间从水面搬到空气里：研究怎样在空中行进、操纵和设计飞行器。','aero- 空气 + 与 nautical 航海的有关的部分 + 学科形式 -ics；近代经法语 aéronautique 等形式发展。',B[:1]+[['法语 aéronautique／英语 aeronautic','空气中的航行相关的'],['英语 aeronautics','航空航行和设计的学科、技术']],'这个词早期与气球飞行有关，后来覆盖飞机等航空技术。aeronautics 作为学科名通常按单数看，不因为结尾 s 就当成多架飞机。','study aeronautics；research in aeronautics；the history of aeronautics。','aeronautics 以大气中的飞行为中心；astronautics 以航天为中心。aerospace 是更能把航空与航天一起覆盖的词。',('She became interested in aeronautics after visiting an aviation museum.','参观航空博物馆后，她对航空学产生了兴趣。'),('The course covers the early history of aeronautics.','这门课介绍航空技术的早期历史。'),sources=['https://www.etymonline.com/word/aeronautics','https://en.wiktionary.org/wiki/aeronautics']),
E('aeronautical','英 /ˌeərəˈnɔːtɪkəl/；美 /ˌeroʊˈnɔtɪkəl/','航空的；航空工程或飞行技术相关的','当空中航行从一个主题变成形容词，就用它说明工程、设计或研究属于哪个领域。','aero- 空气 + nautical 航行的；与 aeronautics 同属近代航空命名，不能把 -nautical 理解成普通的“自然”。',B[:1]+[['nautical 航行相关 + aero-','把航行空间放到空气中'],['英语 aeronautical','航空技术相关的']],'aeronautical engineering 是航空工程，aeronautical research 是航空研究。它常用来谈专业领域与技术；普通机票、航班等则通常直接用 air 或 aviation 的搭配。','aeronautical engineering；aeronautical research；an aeronautical engineer。','aeronautical 说领域归属，aerodynamic 说物体与气流相互作用或外形是否利于空气流过。',('He studied aeronautical engineering at university.','他在大学学的是航空工程。'),('The laboratory carries out aeronautical research.','这个实验室从事航空研究。'),sources=['https://en.wiktionary.org/wiki/aeronautical','https://www.oxfordlearnersdictionaries.com/definition/english/aeronautical'])
]
